-- M1 第二块 PR1：模型网关核心（供应商与模型）。api_key_enc 为 AES-256-GCM 密文。
-- Create "model_providers" table
CREATE TABLE "model_providers" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "kind" character varying NOT NULL DEFAULT 'openai_compat', "dialect" character varying NOT NULL DEFAULT 'generic', "base_url" character varying NOT NULL, "api_key_enc" bytea NULL, "enabled" boolean NOT NULL DEFAULT true, "timeout_seconds" bigint NOT NULL DEFAULT 120, PRIMARY KEY ("id"));
-- Create index "model_providers_name_key" to table: "model_providers"
CREATE UNIQUE INDEX "model_providers_name_key" ON "model_providers" ("name");
-- Create "models" table
CREATE TABLE "models" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "upstream_model" character varying NOT NULL, "thinking" character varying NOT NULL DEFAULT 'off', "tool_choice_policy" character varying NOT NULL DEFAULT 'downgrade', "context_window" bigint NOT NULL DEFAULT 0, "max_output_tokens" bigint NOT NULL DEFAULT 0, "enabled" boolean NOT NULL DEFAULT true, "provider_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "models_model_providers_models" FOREIGN KEY ("provider_id") REFERENCES "model_providers" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "models_name_key" to table: "models"
CREATE UNIQUE INDEX "models_name_key" ON "models" ("name");
